when.set-body:
@{
          var body = (JObject)context.Variables["reqBody"];
          var allowed = new string[] { "model", "messages", "temperature", "top_p", "max_tokens", "max_completion_tokens", "stream", "stop", "presence_penalty", "frequency_penalty", "n", "response_format", "tools", "tool_choice", "logprobs", "top_logprobs", "user", "seed", "reasoning_effort", "stream_options", "parallel_tool_calls", "modalities", "audio", "prediction", "web_search_options", "function_call", "functions", "metadata" };
          var toRemove = new System.Collections.Generic.List<string>();
          // GPT-5+ 계열은 max_tokens 미지원 → max_completion_tokens로 자동 변환 (2026-09-12)
          if (body["max_tokens"] != null && body["max_completion_tokens"] == null) {
            body["max_completion_tokens"] = body["max_tokens"];
            body.Remove("max_tokens");
          }
          // GPT-5+ 계열은 temperature=1만 지원 → GPT 모델이면 1로 강제 (2026-09-12)
          var mdl = (string)body["model"];
          if (mdl != null && mdl.StartsWith("gpt", StringComparison.OrdinalIgnoreCase) && body["temperature"] != null) {
            body["temperature"] = 1;
          }
          // GPT-5+ 계열 미지원 파라미터 일괄 제거 (2026-09-12 실측: 400 Unsupported parameter)
          if (mdl != null && mdl.StartsWith("gpt", StringComparison.OrdinalIgnoreCase)) {
            var unsupported = new string[] { "top_p", "frequency_penalty", "presence_penalty", "stop", "logprobs", "top_logprobs" };
            foreach (var u in unsupported) { if (body[u] != null) { body.Remove(u); } }
            if (body["parallel_tool_calls"] != null && body["tools"] == null) { body.Remove("parallel_tool_calls"); }
          }
          foreach (var prop in body.Properties()) { bool ok = false; foreach (var a in allowed) { if (prop.Name == a) { ok = true; break; } } if (!ok) { toRemove.Add(prop.Name); } }
          foreach (var rm in toRemove) { body.Remove(rm); }
          return body.ToString(Newtonsoft.Json.Formatting.None);
        }

